enum JupiterAdminKitType {
    // Add the fonts to the target and Info.plist (UIAppFonts); fall back to system faces otherwise.
    static func display(_ size: CGFloat) -> Font { .custom("Public Sans", size: size).weight(.semibold) }
    static func body(_ size: CGFloat = 17) -> Font { .custom("Public Sans", size: size) }
    static func mono(_ size: CGFloat = 13) -> Font { .custom("JetBrains Mono", size: size) }
}

enum JupiterAdminKitRadius {
    static let control: CGFloat = 6
    static let card: CGFloat = 12
}

struct PrimaryButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(JupiterAdminKitType.body(16).weight(.medium))
            .frame(maxWidth: .infinity, minHeight: 48)
            .background(Color.brandButton.opacity(configuration.isPressed ? 0.85 : 1))
            .foregroundStyle(Color.brandOnButton)
            .clipShape(RoundedRectangle(cornerRadius: JupiterAdminKitRadius.control, style: .continuous))
    }
}
